// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Reverter rev;

    function setUp() public {
        c = new MyContract();
        rev = new Reverter();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        amount = bound(amount, 0, type(uint128).max);
        vm.deal(address(c), amount);
        vm.prank(address(this));
        bool ok;
        try c.sendTo(address(rev), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "sendTo to a reverting receiver must revert");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
